// Merges live Steam data into the hand-curated game list.
//
// Division of ownership:
//   Steam owns the FACTS     — playtime, last played, developer, genres
//   interests.js owns the CURATION — favourite, status, display order
//
// Steam has no concept of "favourite" or "will play later", so the local list
// stays the source of truth for those and is never overwritten. Games you own
// but have not curated get appended at the end with no status.
//
// steam-games.json is generated by scripts/fetch-steam.mjs (see the daily
// workflow in .github/workflows/steam-sync.yml). It is committed, so this is a
// plain import — no runtime fetch, no API key in the browser, no load latency.

import steamData from './steam-games.json'
import { steam, steamFallback } from './covers'

const BY_APPID = steamData?.games ?? {}

/** minutes → "42h" / "90m" / null when never played */
export function formatPlaytime(minutes) {
  if (!Number.isFinite(minutes) || minutes <= 0) return null
  if (minutes < 60) return `${minutes}m`
  return `${Math.round(minutes / 60)}h`
}

/**
 * @param items local curated items (may carry `appid`)
 * @returns new array: curated items enriched, then un-curated owned games
 */
export function mergeSteam(items) {
  const seen = new Set()

  // 1. curated items, in their hand-sorted order, enriched where Steam knows them
  const merged = items.map(item => {
    if (!item.appid) return item             // non-Steam games (LoL, Valorant…) pass through
    const s = BY_APPID[String(item.appid)]
    if (!s) return item                      // in our list but not owned on Steam

    seen.add(String(item.appid))
    return {
      ...item,
      // `sub` (developer) is only filled in when we never typed one — your
      // hand-written value always wins. Flip the ?? to prefer Steam's.
      sub: item.sub ?? s.developer ?? undefined,
      playtimeMinutes: s.playtimeMinutes,
      playtime: formatPlaytime(s.playtimeMinutes),
      lastPlayed: s.lastPlayed || null,
      recentMinutes: s.playtime2WeeksMinutes ?? 0,
      genres: s.genres ?? [],
      ownedOnSteam: true,
    }
  })

  // 2. owned-but-uncurated games, newest-played first
  const extras = Object.values(BY_APPID)
    .filter(s => !seen.has(String(s.appid)))
    .sort((a, b) => (b.lastPlayed ?? 0) - (a.lastPlayed ?? 0))
    .map(s => ({
      appid: s.appid,
      name: s.name,
      sub: s.developer ?? undefined,
      favourite: false,
      cover: steam(s.appid),
      coverfallback: steamFallback(s.appid),
      playtimeMinutes: s.playtimeMinutes,
      playtime: formatPlaytime(s.playtimeMinutes),
      lastPlayed: s.lastPlayed || null,
      recentMinutes: s.playtime2WeeksMinutes ?? 0,
      genres: s.genres ?? [],
      ownedOnSteam: true,
    }))

  return [...merged, ...extras]
}

/**
 * The "top N right now" list for the home-page tile.
 *
 * Steam's 2-week playtime is the only real signal of what you are ACTUALLY playing,
 * so it wins when present. Until the sync runs that field is 0 everywhere, hence
 * the fallback chain — the tile must render something sensible today:
 *   1. most minutes in the last 2 weeks (real "right now")
 *   2. anything you hand-marked `status: 'playing'`
 *   3. favourites
 *   4. list order, just to fill the slots
 */
export function topPlayed(items, n = 3) {
  const recent = items
    .filter(i => (i.recentMinutes ?? 0) > 0)
    .sort((a, b) => b.recentMinutes - a.recentMinutes)

  const out = []
  for (const list of [recent, items.filter(i => i.status === 'playing'), items.filter(i => i.favourite), items]) {
    for (const item of list) {
      if (out.length >= n) return out
      if (!out.includes(item)) out.push(item)
    }
  }
  return out
}
